  if (walking) return 'walk'
  return 'idle'
}

function renderFrame(stateConfig) {
  const frames = Math.max(1, stateConfig.frames ?? 1)
  // stage 与 sprite 同步尺寸（stage 承载位移动画，sprite 承载帧图与翻转）
